<?php
namespace VPM\Booking;
if(!defined('ABSPATH'))exit;
/** Platform-owned communication. No transparent forwarding of partner free text. */
final class Broker {
    public static function domain():string {$domain=strtolower(trim(Config::secret('VPM_BOOKING_RELAY_DOMAIN')));if($domain==='')return 'relay.example.invalid';Config::require((bool)preg_match('/^(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}$/D',$domain),'invalid_relay_domain');return $domain;}
    public static function alias(array $b):string {
        global $wpdb;$row=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.DB::table('relay').' WHERE booking_id=%d',$b['id']),ARRAY_A);if($row)return $row['address'];$address='b-'.bin2hex(random_bytes(16)).'@'.self::domain();DB::query($wpdb->prepare('INSERT IGNORE INTO '.DB::table('relay').' (booking_id,address) VALUES (%d,%s)',$b['id'],$address));return (string)$wpdb->get_var($wpdb->prepare('SELECT address FROM '.DB::table('relay').' WHERE booking_id=%d',$b['id']));
    }
    public static function redact(string $text,string $email=''):string {
        if($email!=='')$text=str_ireplace(array($email,rawurlencode($email)),'[Kontakt über Plattform]',$text);
        return (string)preg_replace('/[\p{L}\p{N}._%+\-]+@[\p{L}\p{N}.\-]+\.[\p{L}]{2,}/u','[Kontakt über Plattform]',$text);
    }
    public static function sanitize($value,string $email='') {if(is_string($value))return self::redact($value,$email);if(is_array($value)){foreach($value as $k=>$v){if(in_array($k,array('customer_email','request_hash','request_key'),true)){unset($value[$k]);continue;}$value[$k]=self::sanitize($v,$email);}}return $value;}
    public static function adapter(array $b):array {
        // Adapter receives a strict subset, never raw database rows or customer/marketing identifiers.
        $q=Core::snapshot($b);$q=array_intersect_key($q,array_flip(array('base','currency','partner','airport','travel','offer_selection','offer_terms','booking_rules','fulfilment','cancellation_decision')));$out=array_intersect_key($b,array_flip(array('id','public_id','partner_id','locale','state','payment_state')));$out['customer_email']=self::alias($b);$out['snapshot']=wp_json_encode(self::sanitize($q,$b['customer_email']));return $out;
    }
    public static function submit(int $partner,string $reference,string $body,string $key):void {
        Tenants::authorize($partner,true);Config::key($key);$body=trim(sanitize_textarea_field($body));Config::require(strlen($body)>=3&&strlen($body)<=2000,'invalid_partner_message');$b=Core::booking($reference);Config::require((int)$b['partner_id']===$partner,'portal_forbidden');
        DB::tx(function()use($partner,$b,$body,$key){global $wpdb;$b=Core::booking($b['public_id'],true);$old=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.DB::table('messages').' WHERE booking_id=%d AND request_key=%s',$b['id'],$key),ARRAY_A);if($old){Config::require(hash_equals(Config::open($old['payload'])['body'],$body),'idempotency_conflict');return;}$id=DB::insert('messages',array('booking_id'=>$b['id'],'partner_id'=>$partner,'request_key'=>$key,'payload'=>Config::seal(array('body'=>$body)),'state'=>'pending','created_at'=>time()));Operations::audit('partner.message_review_requested','message',$id);Automation::event('message-review:'.$id,'operations.partner_message_review','transactional',array('message_id'=>$id,'booking_id'=>$b['public_id'],'partner_id'=>$partner));});
    }
    public static function review(int $id,bool $approve,string $approved):void {
        Config::require(current_user_can('manage_options'),'permission_denied');DB::tx(function()use($id,$approve,$approved){$m=DB::row('messages','id',$id,true);Config::require((bool)$m,'message_not_found');if($m['state']!=='pending')return;$b=DB::row('bookings','id',$m['booking_id'],true);$body=trim(sanitize_textarea_field($approved));if($approve){Config::require(strlen($body)>=3&&strlen($body)<=2000,'invalid_partner_message');Config::require(!preg_match('~(?:https?://|www\.|mailto:|[\p{L}\p{N}._%+\-]+@[\p{L}\p{N}.\-]+\.[\p{L}]{2,})~iu',$body),'message_external_contact_requires_separate_review');Automation::booking_event($b,'booking.partner_message_approved',array('message_id'=>$id,'message'=>$body,'reply_policy'=>'platform_only'),'message:'.$id);}DB::update('messages',array('state'=>$approve?'approved':'rejected','reviewed_at'=>time(),'reviewer_id'=>get_current_user_id(),'payload'=>Config::seal(array('body'=>Config::open($m['payload'])['body'],'approved_body'=>$approve?$body:''))),array('id'=>$id));Operations::audit($approve?'partner.message_approved':'partner.message_rejected','message',$id);});
    }
    public static function pending_profile(int $partner,array $data):void {global $wpdb;DB::query($wpdb->prepare('INSERT INTO '.DB::table('profile_reviews').' (partner_id,payload,created_at) VALUES (%d,%s,%d) ON DUPLICATE KEY UPDATE payload=VALUES(payload),created_at=VALUES(created_at)',$partner,Config::seal($data),time()));Operations::audit('partner.logistics_review_requested','partner',$partner);}
    public static function profile_review(int $partner,bool $approve):void {Config::require(current_user_can('manage_options'),'permission_denied');global $wpdb;DB::tx(function()use($partner,$approve,$wpdb){$row=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.DB::table('profile_reviews').' WHERE partner_id=%d FOR UPDATE',$partner),ARRAY_A);Config::require((bool)$row,'profile_review_not_found');if($approve){$data=Config::open($row['payload']);foreach($data['points']??array()as $key=>$point)foreach(array('latitude','longitude')as $coordinate)if(isset($point[$coordinate]))$data['points'][$key][$coordinate]=number_format((float)$point[$coordinate],8,'.','');Logistics::save($partner,$data);}$wpdb->delete(DB::table('profile_reviews'),array('partner_id'=>$partner));Operations::audit($approve?'partner.logistics_approved':'partner.logistics_rejected','partner',$partner);});}
    public static function admin():void {
        Config::require(current_user_can('manage_options'),'permission_denied');global $wpdb;echo '<h2 id="communication">Kommunikation – Plattformfreigabe</h2><p>Partnertexte werden nicht ungeprüft als Kunden-E-Mail versendet. Inhalt, Signaturen und mögliche Umgehungsaufforderungen vor Freigabe prüfen. Absender und Antwortadresse bleiben bei der Plattform.</p>';
        foreach($wpdb->get_results('SELECT * FROM '.DB::table('messages')." WHERE state='pending' ORDER BY id LIMIT 50",ARRAY_A)as $m){$body=Config::open($m['payload']);echo '<form method="post">';wp_nonce_field('vpm_booking_operations');echo '<input type="hidden" name="vpm_operation" value="message_review"><input type="hidden" name="id" value="'.(int)$m['id'].'"><h3>Partner '.(int)$m['partner_id'].' · Buchung '.(int)$m['booking_id'].'</h3><label>Geprüfter Nachrichtentext<textarea name="body" class="large-text" rows="4">'.esc_textarea($body['body']).'</textarea></label><button class="button button-primary" name="decision" value="approve">Freigeben</button> <button class="button" name="decision" value="reject">Ablehnen</button></form>';}
        foreach($wpdb->get_results('SELECT * FROM '.DB::table('profile_reviews').' ORDER BY created_at LIMIT 50',ARRAY_A)as $r){echo '<form method="post">';wp_nonce_field('vpm_booking_operations');echo '<input type="hidden" name="vpm_operation" value="profile_review"><input type="hidden" name="partner_id" value="'.(int)$r['partner_id'].'"><h3>Anfahrt/Kontakte: Partner '.(int)$r['partner_id'].'</h3><pre>'.esc_html(wp_json_encode(Config::open($r['payload']),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)).'</pre><button class="button button-primary" name="decision" value="approve">Geprüfte Angaben freigeben</button> <button class="button" name="decision" value="reject">Ablehnen</button></form>';}
    }
}
